import { defineChannel, POST, publicEndpoint } from "@grok/agent-sdk/channels";
import { z } from "zod";
import { formatQueuePrompt, parseQueueEvent } from "../lib/parse-queue-event.js";
import { verifyTrackerWebhook } from "../lib/verify-webhook.js";

export default defineChannel({
  auth: [publicEndpoint()],
  routes: [
    POST("/", {
      description: "Signed Linear or Jira issue-created webhook",
      bodySchema: z.unknown(),
      handler: async (request, route) => {
        const rawBody = await request.text();
        const verified = verifyTrackerWebhook({
          rawBody,
          linearSignature: request.headers.get("linear-signature"),
          hubSignature:
            request.headers.get("x-hub-signature-256") ?? request.headers.get("x-hub-signature"),
          linearSecret: process.env.LINEAR_WEBHOOK_SECRET,
          jiraSecret: process.env.JIRA_WEBHOOK_SECRET,
          nowMs: Date.now(),
        });
        if (!verified.ok) {
          return new Response(null, { status: verified.status });
        }
        const parsed = parseQueueEvent(route.body);
        if (!parsed.ok) {
          return new Response(null, { status: 202 });
        }
        route.waitUntil(
          route.send(formatQueuePrompt(parsed.issue), {
            continuationToken: parsed.issue.identifier,
            admission: "coalesce",
            title: parsed.issue.title === "" ? undefined : parsed.issue.title,
          }),
        );
        return new Response(null, { status: 202 });
      },
    }),
  ],
});
